text_intro2.content:
Dynamic BBox là đối tượng đặc biệt, nó tự động vẽ ra nhiều bounding boxes theo dữ liệu nạp vào, bạn phải liên kết nó với một tag kiểu Array, dữ liệu bên trong trông giống thế này: 
   [
{ 'id': 'sample_1', 'x': 10, 'y': 10, 'w': 120, 'h': 80, label: 'somelabel', 'color': '#00ffff' },
{ 'id': 'someid', 'x': 60, 'y': 50, 'w': 90, 'h': 60, label: 'hello', color: '#202020' }
   ] 
 LƯU Ý: PHẢI CÓ DẤU '' CHO KEY

config.script_content:
if (IN.image_path_list.length >= 0){
   OUT.source_image = IN.image_path_list.shift()
   OUT.End = false;
} else {
   OUT.End = true;
}

function safeParse(data) {
    if (typeof data === 'string') {
        try { return JSON.parse(data); } catch (e) { return []; }
    }
    return Array.isArray(data) ? data : [];
}

try {
    // 1. Đọc danh sách tên các Bbox từ cổng IN
    let bboxNames = safeParse(IN.bbox_names);

    let rawXywhList = [];

    // 2. Duyệt qua từng tên UI để trích xuất tọa độ
    for (let i = 0; i < bboxNames.length; i++) {
        let name = bboxNames[i];

        // Gọi API UI.get() để lấy Object thuộc tính của Component
        let comp = UI.get(name);

        if (comp) {

            // Tạo thêm một list thuần xywh dạng [[x,y,w,h], ...] để dễ feed vào AI
            rawXywhList.push([comp.x, comp.y, comp.w, comp.h]);
        } else {
            // Ghi log cảnh báo nếu gõ sai tên UI
            ENGINE.log("Cảnh báo: Không tìm thấy UI component có tên '" + name + "'");
        }
    }

    OUT.xywh_list = rawXywhList;          

} catch (error) {
    ENGINE.log("LỖI TRÍCH XUẤT TỌA ĐỘ: " + error.message);
}

